from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class CellBlock(OperationPrototype):
    def __init__(self, bts):
        super(CellBlock, self).__init__(bts)
        self.bts.set_up_parent_rmods_for_cells()
        self.operation_details = {
            "Timeout": None,
            "Operation": "Cell Block",
            "Start point": "Block cell request",
            "End point": "Cell down",
            "Requirement": "OM_GEN_SFS_PERF_CAP.13255",
        }

    def get_kpi(self, cell_dist_name):
        """
        Gets Cell block procedure timeout.
        Requirement: OM_GEN_SFS_PERF_CAP.13255
        :param cell_dist_name: dist_name of the cell, which KPI cell block timeout will be applied to
        :type cell_dist_name: str
        :return: dictionary with timeout, requirement and operation description for cell unblock
        :rtype: dict
        """
        self.operation_details["Timeout"] = 10 + self.restrictions.\
            get_additional_time_depending_on_cell_type(cell_dist_name) + self.restrictions.\
            use_restrictions_from_OM_GEN_SFS_PERF_CAP_13258(cell_dist_name)
        return self.operation_details
